_static_wrap() {
    cat <<-'ARGCEOF'
	auto	Wrap text automatically
	never	Never wrap text
	character	Wrap at character boundaries
ARGCEOF
}

_static_color() {
    cat <<-'ARGCEOF'
	auto	Enable colors only when an interactive terminal is detected
	never	Never use colored output
	always	Always use colored output
ARGCEOF
}

_static_decorations() {
    cat <<-'ARGCEOF'
	auto	Enable decorations only when an interactive terminal is detected
	never	Never show decorations
	always	Show decorations even when piping output
ARGCEOF
}

_static_strip_ansi() {
    cat <<-'ARGCEOF'
	auto	Strip escape sequences unless the syntax is plain text
	always	Always strip escape sequences
	never	Never strip escape sequences
