}

_choice_language() {
    bat --list-languages 2>/dev/null | gawk -F: '{
        name = $1
        exts = substr($0, length(name) + 2)
        print name "\t" exts
        count = split(exts, parts, ",")
        for (i = 1; i <= count; i++) {
            print parts[i] "\t" name
        }
    }'
}

_choice_map_syntax() {
    _argc_util_mode_kv :
    if [[ -z "$argc__kv_prefix" ]]; then
        return 0
    fi
    bat --list-languages 2>/dev/null | gawk -F: '{ print $1 }'
}

_choice_pager() {
    _choice_command | _argc_util_transform nospace
}

_choice_theme() {
    bat --list-themes 2>/dev/null
    printf '%s\n' auto auto:always auto:system dark light
}

_choice_theme_name() {
